output Y0;
output Y1;
output Y2;
output Y3;
output Y4;
output Y5;
output Y6;
output Y7;

wire notA;
wire notB;
wire notC;

assign notA = ~A;
assign notB = ~B;
assign notC = ~C;

assign Y0 = notA & notB & notC; // Y0 = A'B'C'
assign Y1 = notA & notB & C;    // Y1 = A'B'C
assign Y2 = notA & B & notC;     // Y2 = A'BC'
