description:
Design a two-state branch prediction circuit. This module uses a state machine to predict whether a branch will be taken based on previous outcomes. It switches between two states, PREDICT_0 (not taken) and PREDICT_1 (taken), depending on the input signal indicating whether the last branch was taken (taken_i) and operates based on a clock signal. When enabled and the reset signal is low, the module updates its state and outputs a prediction based on the current state, where the output is high only when the state is PREDICT_1.
module top_module(
  input clock, reset, enable, taken_i,
  output prediction_o
);

code:
module top_module(
  input clock, reset, enable, taken_i,
  output prediction_o
);// Define the states
  parameter PREDICT_0 = 1'b0;
  parameter PREDICT_1 = 1'b1;

  // Define the state register
  reg [0:1] state_reg;
  always @(posedge clock) begin
    if (reset) begin
      state_reg <= PREDICT_0;
    end else if (enable) begin
      case (state_reg)
        PREDICT_0: begin
          if (taken_i) begin
            state_reg <= PREDICT_1;
          end
        end
        PREDICT_1: begin
          if (!taken_i) begin
            state_reg <= PREDICT_0;
          end
        end
      endcase
    end
  end

  // Define the output
  assign prediction_o = (state_reg == PREDICT_1);

endmodule

