description:
Implement the Verilog module based on the following description.
Build a 3-bit Johnson counter with synchronous active high reset signal.
// (1) reset: Resets the counter to 3'b000.
// (2) q: The value of the counter.

module top_module(
    input clk,
    input reset,
    output reg [2:0] q);

code:
module top_module(
    input clk,
    input reset,
    output reg [2:0] q
);

    always @(posedge clk) begin
        if (reset) begin
            // Synchronous reset: Reset the counter to 3'b000
            q <= 3'b000;
        end else begin
            // Johnson counter: Invert the MSB and shift right
            q <= {~q[2], q[2:1]};
        end
    end

endmodule

