        input [3:0] bit_pos;
        input bit_val;
        begin
            @(posedge clk);
            num = bit_pos;
            rs232_rx = bit_val;
        end
        endtask

    task commit_data;

        begin
            @(posedge clk);
            num = 9;
        end
        endtask

    task testcase001;

        begin
            test_num = test_num + 1;
            $display("Testcase %0d: Receiving 0x55", test_num);
            reset_dut();


            load_bit(0, 1);
            load_bit(1, 0);
            load_bit(2, 1);
            load_bit(3, 0);
            load_bit(4, 1);
            load_bit(5, 0);
            load_bit(6, 1);
            load_bit(7, 0);

            commit_data();


            @(posedge clk);
            #2;


            #1;



            check_outputs(8'h55, 1'b1, 1'b1);
        end
        endtask

