description:
Design a simple calculator module that performs basic arithmetic operations based on a 32-bit input signal. It extracts two 8-bit operands and a 4-bit operator from the input data, and upon receiving a trigger signal, it executes the corresponding arithmetic operation, including addition, subtraction, multiplication, and division. The result is clamped to prevent overflow or underflow by restricting it within the signed 32-bit integer range. The module effectively utilizes combinational logic for operand extraction and sequential logic for operation execution, making it suitable for basic arithmetic processing tasks.
module top_module(
    input [31:0] data,
    input trigger,
    output reg [31:0] result
);

code:
module top_module(
    input [31:0] data,
    input trigger,
    output reg [31:0] result
);reg [7:0] operand1;
    reg [7:0] operand2;
    reg [3:0] operator;

    always @(*) begin
        operand1 = data[7:0];
        operand2 = data[15:8];
        operator = data[23:16];
    end

    always @(posedge trigger) begin
        case(operator)
            4'b0000: result <= $signed(operand1) + $signed(operand2);
            4'b0001: result <= $signed(operand1) - $signed(operand2);
            4'b0010: result <= $signed(operand1) * $signed(operand2);
            4'b0011: begin
                        if (operand2 == 0) begin
                            result <= 32'h7FFFFFFF; // Maximum value for signed 32-bit integer
                        end else begin
                            result <= $signed(operand1) / $signed(operand2);
                        end
                     end
            default: result <= 0;
        endcase

        // Clamp result to maximum or minimum value if overflow or underflow occurs
        if (result > 32'h7FFFFFFF) begin
            result <= 32'h7FFFFFFF;
        end else if (result < 32'h80000000) begin
            result <= 32'h80000000;
        end
    end

endmodule

