module comparator(A, B, A_gt_B, A_eq_B, A_lt_B);
input [3:0] A, B;
output A_gt_B, A_eq_B, A_lt_B;
reg A_gt_B, A_eq_B, A_lt_B;

always @(A or B) begin
    if (A > B) begin
        A_gt_B = 1;
        A_eq_B = 0;
        A_lt_B = 0;
    end else if (A == B) begin
        A_gt_B = 0;
        A_eq_B = 1;
        A_lt_B = 0;
    end else begin
        A_gt_B = 0;
        A_eq_B = 0;
        A_lt_B = 1;
    end
end

endmodule

