// Input f goes to a two-input NOR gate, a two-input OR gate, and a two-input AND gate. The outputs of these gates go to D flip-flops. The outputs of the D flip-flops are connected to a three-input NAND gate, whose output is Y.
module fsm_module8 (
	input clk,
	input f,
	output y);

code:
module fsm_module8 (
	input clk,
	input f,
	output y);reg [2:0] state = 0;

always @(posedge clk) begin
	state <= { ~(state[2] | f), state[1] | f, state[0] & f };
end

assign y = ~(state[2] & state[1] & state[0]);

endmodule

