            RAddr1 = 4'd10;
            RAddr2 = 4'd10;
            EX_WAddr = 4'd10;
            EX_WDataSc2 = 1'b1;
            EX_RFWen = 1'b1;
            #1;

            check_outputs(1'b1);
        end
        endtask

    task testcase008;

        begin
            test_num = 8;
            $display("Test %0d: Match on RAddr1 but opCode is a non-reading instruction (e.g. 4'hF).", test_num);
            opCode = 4'hF;
            RAddr1 = 4'd12;
            RAddr2 = 4'd13;
            EX_WAddr = 4'd12;
            EX_WDataSc2 = 1'b1;
